"// Eigenes Plugin für die VN Timeline Engine\n// Anleitung: siehe PLUGINS.md in diesem Ordner\nVNPlugin.register({\n  id: '__ID__',\n  name: 'Mein Plugin',\n  version: '1.0',\n  description: 'Beschreibe hier kurz, was dein Plugin macht.',\n  actions: {\n    hallo: {\n      label: 'Hallo sagen',\n      params: [\n        { key: 'text', label: 'Text', type: 'text', default: 'Hallo aus dem Plugin!' },\n        { key: 'gold', label: 'Gold geben', type: 'number', default: 5 }\n      ],\n      // Läuft, wenn die Aktion im Spiel ausgelöst wird. Ein Promise lässt das Spiel warten.\n      run(params, ctx) {\n        ctx.money.add('Gold', Number(params.gold) || 0);\n        return ctx.message(params.text);\n      }\n    }\n  },\n  hooks: {\n    onSceneEnter(scene, ctx) { /* z. B. Statistik zählen */ }\n  }\n});": "// Your own plugin for VN Timeline Engine\n// Guide: see PLUGINS.md in this folder\nVNPlugin.register({\n  id: '__ID__',\n  name: 'My plugin',\n  version: '1.0',\n  description: 'Briefly describe what your plugin does.',\n  actions: {\n    hallo: {\n      label: 'Say hello',\n      params: [\n        { key: 'text', label: 'Text', type: 'text', default: 'Hello from the plugin!' },\n        { key: 'gold', label: 'Give gold', type: 'number', default: 5 }\n      ],\n      // Runs when the action is triggered in the game. A Promise makes the game wait.\n      run(params, ctx) {\n        ctx.money.add('Gold', Number(params.gold) || 0);\n        return ctx.message(params.text);\n      }\n    }\n  },\n  hooks: {\n    onSceneEnter(scene, ctx) { /* e.g. count statistics */ }\n  }\n});",
