"Begriffe aus deinem Spiel (Orte, Personen, Fachwörter). Taucht ein Begriff in einem Dialog auf, wird er unterstrichen und lässt sich anklicken. Gefundene Einträge sammelt der Spieler im Pausenmenü unter „Glossar“.": "Terms from your game (places, people, jargon). When a term appears in a dialogue line, it is underlined and can be clicked. The player collects found entries in the pause menu under “Glossary”.",
