"Bei Niederlage ausführen": "Run on defeat",
"Bei Stufenaufstieg von": "On level-up of",
"Bei der Antwort rechts „Ziel“ wählen.": "Pick a “Target” for the answer on the right.",
"Bei einem Spielsystem (Karte, Quest, Skilltree, Kampf, Aufbau) fehlt etwas oder passt nicht zusammen.": "Something is missing or doesn't fit in a game system (map, quest, skill tree, battle, building).",
"Bei einem Ziel unter „Beim Erreichen ausführen“ die Aktion „♥ Beziehung ändern“ hinzufügen.": "For a goal, add the action “♥ Change relationship” under “Run when reached”.",
"Bei jedem Betreten": "Every time you enter",
"Bei „Beim Klick“ die Aktion „Zu Szene springen“ wählen.": "Under “On click”, choose the action “Jump to scene”.",
"Bei „Beim Klick“ die Aktion „♥ Beziehung ändern“ hinzufügen.": "Under “On click”, add the action “♥ Change relationship”.",
"Bei „Was wird gekauft?“ die Bäckerei wählen, Preis 500 Gold.": "Under “What is being bought?”, pick the bakery, price 500 gold.",
