"Beim Neustart wird das Update installiert. Dein Projekt wird vorher gespeichert.": "The update is installed on restart. Your project is saved first.",
"Beim Sieg ausführen": "Run on victory",
"Beim Spielstart erscheint immer das Logo der VN Timeline Engine (Pflicht: mindestens 5 Sekunden, ab 2 Sekunden mit Klick überspringbar). Deine eigenen Logos – Bilder oder Videos – können davor oder danach kommen, so viele du willst.": "When the game starts, the VN Timeline Engine logo always appears (required: at least 5 seconds, can be skipped with a click after 2 seconds). Your own logos – images or videos – can come before or after it, as many as you like.",
"Beim Spielstart erscheint immer kurz das Logo der VN Timeline Engine (Pflicht, ca. 2 Sekunden, mit Klick überspringbar). Dein eigenes Studio-Logo kann davor oder danach kommen.": "When the game starts, the VN Timeline Engine logo always appears briefly (required, about 2 seconds, skippable with a click). Your own studio logo can come before or after it.",
