"Clips löschen?": "clips delete?",
"Clips verschieben, am rechten Rand ziehen zum Verlängern, Rechtsklick für mehr. Entf löscht, Strg+Z macht rückgängig.": "Move clips, drag the right edge to extend, right-click for more. Del deletes, Ctrl+Z undoes.",
