"Das": "That",
"Das Bild wiederholt sich als Kachel und zieht endlos vorbei, z. B. Wolken, Himmel oder Landschaft aus dem Zugfenster. Gezeichnet wird nur, was im Fenster sichtbar ist. Am schönsten mit Bildern, deren Ränder zusammenpassen.": "The image repeats as a tile and scrolls by endlessly, e.g. clouds, sky or landscape from a train window. Only what is visible in the window is drawn. Looks best with images whose edges match.",
"Das Engine-Logo ist davon ausgenommen: Es lässt sich immer erst nach 2 Sekunden überspringen.": "The engine logo is an exception: it can only be skipped after 2 seconds.",
"Das Ergebnis wird aus dem Seed des Durchlaufs und der ID der Quelle berechnet. Zurückladen bringt dieselbe Beute, ein neues Spiel neue.": "The result is computed from the playthrough’s seed and the source’s ID. Reloading gives the same loot, a new game new loot.",
"Das Gebäude erscheint erst, wenn irgendwo die Aktion „🏰 Gebäude freischalten“ ausgeführt wird – am einfachsten per Rechtsklick auf ein Hub-Objekt → Bausteine → „Wird gekauft …“.": "The building only appears once the action “🏰 Unlock building” runs somewhere – easiest via right-click on a hub object → Building blocks → “Can be bought …”.",
"Das Gebäude ist auf „Durch Aktion“ gestellt, aber keine Aktion „🏰 Gebäude freischalten“ zeigt darauf. Spieler bekommen es nie.": "The building is set to “By action”, but no “🏰 Unlock building” action points to it. Players never get it.",
"Das Grundgerüst (Programm und Browser-Technik) ist bei jedem Windows-Spiel gleich groß, auch bei einem winzigen Spiel. Beim Web-Spiel übernimmt das der Browser.": "The base (program and browser technology) is the same size for every Windows game, even a tiny one. For the web game the browser takes care of that.",
"Das Inventar hat eigene Bilder für Fenster und Plätze:": "The inventory has its own images for window and slots:",
"Das Original wurde geändert, seit übersetzt wurde": "The original was changed since it was translated",
"Das Spiel beginnt hier": "The game starts here",
"Das Spiel bleibt bei dieser Zeile stehen, bis der Spieler etwas getan hat – z. B. das Inventar geöffnet oder etwas angezogen. Gut für Tutorials im eigenen Spiel.": "The game stays on this line until the player has done something – e.g. opened the inventory or put something on. Good for tutorials in your own game.",
"Das Spiel lädt nur die Plugins, die du mitlieferst – unverändert. Fremde oder veränderte Dateien werden ignoriert.": "The game only loads the plugins you ship – unchanged. Foreign or changed files are ignored.",
"Das Spielsystem „Ausrüstung“ ist aus – unter Spielsysteme → Übersicht einschalten.": "The game system “Equipment” is off – turn it on under Game systems → Overview.",
"Das Sprecher-Skript listet alle Zeilen pro Figur mit ID, damit die Aufnahmen richtig benannt werden.": "The speaker script lists all lines per character with ID so the recordings are named correctly.",
"Das Update wird im Hintergrund geladen. Du kannst dabei weiterarbeiten.": "The update downloads in the background. You can keep working.",
"Das aktuelle Ziel dauert länger als geplant – alles läuft schneller.": "The current goal takes longer than planned – everything runs faster.",
"Das ergibt nur Matsch.": "That only makes mush.",
"Das funktioniert hier nicht.": "That doesn’t work here.",
"Das gehört dir schon.": "That's already yours.",
"Das gleiche Geschenk wirkt jedes Mal nur halb so stark": "The same gift only works half as well each time",
"Das ist eine Beispielzeile, damit du siehst, wie die Sprechblase im Spiel wirkt.": "This is an example line so you can see how the speech bubble looks in the game.",
"Das ist kein Deckel: Im Spiel steigt der Wert immer bis 100 %. Es fehlen nur noch Stellen, an denen es Punkte gibt. Während du baust, ist das normal.": "This is not a cap: in the game the value can always rise to 100 %. There just aren't enough places that give points yet. That's normal while you're building.",
"Das kann man hier nicht benutzen.": "You can’t use that here.",
"Das passende System ist gerade aus": "The matching system is currently off",
"Das passt nicht zusammen.": "Those don’t go together.",
