"Den Händler fragen": "Ask the merchant",
"Den Keller betreten": "Enter the cellar",
"Der Antwort ein Ziel geben.": "Give the answer a target.",
"Der Dietrich ist abgerutscht …": "The lockpick slipped …",
"Der Filter färbt Hintergrund und Figuren um. „Rückblende“ bringt Sepia und weiche, helle Ränder mit.": "The filter recolors background and characters. “Flashback” adds sepia and soft, bright edges.",
"Der Klickpunkt ist die Stelle im Bild, die genau auf das Ziel zeigt, z. B. die Spitze eines Pfeils. Fahre über die Vorschau, um den Zeiger zu sehen.": "The click point is the spot in the image that points exactly at the target, e.g. the tip of an arrow. Hover over the preview to see the cursor.",
"Der Laden ist leer.": "The shop is empty.",
"Der Spieler klickt das Objekt an, bestätigt den Kauf, das Geld wird abgezogen und es passiert, was du hier wählst. Ohne Variablen, ohne Bedingungen.": "The player clicks the object, confirms the purchase, the money is taken and whatever you choose here happens. No variables, no conditions.",
"Der Windows-Export funktioniert nur in der fertigen Programmversion (.exe).": "Windows export only works in the finished program version (.exe).",
"Der verlorene Schlüssel": "The lost key",
"Design · Auswahl": "Design · Choice",
"Design · Figur": "Design · Character",
"Design · Hintergrund": "Design · Background",
"Design · Hub-Hintergrund": "Design · Hub background",
"Design · Hub-Objekt": "Design · Hub object",
"Design · Menü-Button": "Design · Menu button",
"Design · Sprechblase": "Design · Speech bubble",
"Design ändern …": "Change design …",
"Detail-Feld": "Detail panel",
"Dialog": "Dialogue",
"Dialog danach einfügen": "Insert dialogue after",
"Dialog-Text": "Dialogue text",
"Dialog: „": "Dialogue: “",
"Dialoge": "dialogue lines",
"Dialoge ab Schritt": "dialogue lines from step",
"Dialoge, Ren'Py": "Dialogue, Ren'Py",
"Die 10 größten Dateien": "The 10 largest files",
"Die Antwort steht im letzten Schritt der Szene und die Szene hat kein „Danach weiter zu“. Wählt der Spieler sie, ist das Spiel zu Ende.": "The answer is in the scene's last step and the scene has no “Then continue to”. If the player picks it, the game ends.",
"Die Aufnahme ist leer geblieben.": "The recording stayed empty.",
"Die Ausrüstung erscheint oben im Inventar (Taste I). Ein Klick auf einen belegten Platz legt den Gegenstand ab. Gibt der Spieler einen getragenen Gegenstand ab, wird er automatisch abgelegt.": "The equipment appears at the top of the inventory (key I). Clicking a filled slot takes the item off. If the player gives away a worn item, it is taken off automatically.",
"Die Bühne im Editor ist genau so groß wie später das Spiel. Du kannst das später beim Exportieren noch ändern.": "The stage in the editor is exactly as big as the game later. You can still change this when exporting.",
"Die Datei konnte nicht gelesen werden.": "The file could not be read.",
"Die Engine hat erkannt, dass ein Objekt genau diesen Umweg benutzt.": "The engine noticed that an object uses exactly this workaround.",
"Die Engine kann sie nicht prüfen. Im Spiel gilt sie deshalb als nicht erfüllt, und was daran hängt, erscheint nie.": "The engine can't check it. In the game it counts as not met, so whatever depends on it never appears.",
"Die Engine prüft jedes eingeschaltete System, ob es so im Spiel funktionieren kann.": "The engine checks every enabled system to see whether it can work like this in the game.",
"Die Engine sucht im ganzen Projekt nach der passenden Aktion.": "The engine searches the whole project for the matching action.",
"Die Engine verfolgt alle Wege ab der Startszene. Kommt sie nirgends bei dieser Szene an, erscheint die Meldung.": "The engine follows every path from the start scene. If none of them reaches this scene, this message appears.",
"Die Engine zählt alle ♥-Punkte zusammen, die eine Figur im ganzen Spiel bekommen kann – Startwert plus jede Stelle, an der es Punkte gibt. Liegt eine Stufe mit Belohnung darüber, kann kein Spieler sie erreichen.": "The engine adds up all ♥ points a character can get in the whole game – start value plus every place that gives points. If a level with a reward is higher than that, no player can reach it.",
"Die Figur wird über ihren Namen erkannt (Sprecher = Name der Figur am Clip oder Dateiname).": "The character is recognized by its name (speaker = character name on the clip or file name).",
"Die Kamera bewegt die ganze Bühne: Hintergrund, Figuren und Effekte. Dialog und Buttons bleiben stehen. Mit Parallax-Ebenen (am Hintergrund) entsteht Tiefe.": "The camera moves the whole stage: background, characters and effects. Dialogue and buttons stay in place. Parallax layers (on the background) create depth.",
"Die Spielzeit läuft in Tageszeiten. Sie ändert sich nur durch die Aktion „Zeit vergehen lassen“ (z. B. nach einem Job oder beim Schlafen). Prüfen kannst du sie mit der Bedingung „Zeit / Kalender“.": "Game time runs in time slots. It only changes through the action “Let time pass” (e.g. after a job or when sleeping). Check it with the condition “Time / calendar”.",
"Die Stelle ist gerade nicht sichtbar – vielleicht erst den richtigen Bereich öffnen.": "That spot isn’t visible right now – maybe open the right area first.",
"Die Szene auswählen.": "Select the scene.",
"Die Truhe öffnen": "Open the chest",
"Die Vorlage legt ein passendes Skelett über die Figur. Danach ziehst du die Gelenke an die richtigen Stellen und ergänzt Haare, Flügel oder einen Schweif als Kette.": "The template places a fitting skeleton over the character. Then drag the joints to the right places and add hair, wings or a tail as a chain.",
"Die Vorschau benutzt Bilder aus deinem Projekt, damit du sofort siehst, wie es im Spiel wirkt.": "The preview uses images from your project so you can see right away how it looks in the game.",
"Die Wache bestechen (50 Gold)": "Bribe the guard (50 gold)",
"Die Wolken stehen still. Das ändern wir!": "The clouds are standing still. Let’s change that!",
