"Diese Meldung nicht mehr zeigen (unter Fehlerliste wieder einblendbar)": "Don't show this message again (can be shown again in the problem list)",
"Diese Sprache gibt es schon": "This language already exists",
"Diese Szene läuft auch auf schwächeren Rechnern flüssig.": "This scene also runs smoothly on weaker computers.",
