"Doppelklick öffnet eine Szene. Rechtsklick auf eine Szene oder eine Linienbeschriftung für neue Pfade.": "Double-click opens a scene. Right-click a scene or a line label for new paths.",
"Doppelklick: Farb-/Licht-Ebene · Partikel und Filter aus „Effekte“ links hierher ziehen": "Double-click: color/light layer · drag particles and filters from “Effects” on the left here",
"Doppelklick: Kamerafahrt (Zoom, Schwenk, Wackeln) · Vorlagen aus „Effekte“ links": "Double-click: camera move (zoom, pan, shake) · templates from “Effects” on the left",
"Doppelklicke in die Kamera-Spur, um einen Kamera-Clip anzulegen.": "Double-click the camera track to create a camera clip.",
