"Drei Arten: Idle (Dauer-Schleife einer Figur), Geste (einmalig, z. B. Winken) und Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton.": "Three kinds: idle (continuous loop of a character), gesture (once, e.g. waving) and cutscene with background, several characters, camera and sound.",
"Drei Stellen: Hier Figuren einschalten. In jeder Antwort steht ein Feld „♥ Beziehung“ (+10 Ray). Und überall unter „Nur wenn“ gibt es „♥ Beziehung … ab Stufe Freund“. Den Bildschirm „Beziehungen“ öffnet der Spieler mit Taste B oder im Pausenmenü.": "Three places: switch characters on here. Every answer has a field “♥ Relationship” (+10 Ray). And everywhere under “Only if” there is “♥ Relationship … from stage Friend”. The player opens the “Relationships” screen with key B or in the pause menu.",
"Druiden-Baum": "Druid tree",
