"Du hast die neueste Version.": "You have the latest version.",
"Du hast nicht genug für den Einsatz.": "You don’t have enough for the stake.",
"Du hast nichts, was du verschenken könntest.": "You have nothing you could give.",
"Du schleppst Krüge, wischst Tische und lächelst freundlich.": "You haul mugs, wipe tables and smile kindly.",
