"Ebenen & Outfits": "Layers & outfits",
"Ebenen von unten nach oben. Alle Bilder einer Figur sollten gleich groß sein (gleiche Leinwand), damit sie genau übereinander passen.": "Layers from bottom to top. All images of a character should be the same size (same canvas) so they fit exactly on top of each other.",
"Ebenen-Figur": "Layer character",
"Ebenen-Figuren (Körper, Gesicht, Outfit) legst du oben unter „Figuren“ an.": "You create layer characters (body, face, outfit) above under “Characters”.",
