"Effekte": "Effects",
"Eigene": "Custom",
"Eigene Bilder (z. B. ein PNG mit Feuerball) erscheinen kurz groß über dem Ziel. So lassen sich alle Effekte austauschen.": "Your own images (e.g. a PNG of a fireball) briefly appear large over the target. This way every effect can be replaced.",
"Eigene Inhalte legst du unter Spielsysteme": "Create your own content under Game systems",
"Eigene Musik für diese": "Own music for this",
"Eigene Namensfarbe": "Own name color",
"Eigene Punkte (z. B. Skillpunkte, Ruhm, Talentpunkte)": "Custom points (e.g. skill points, fame, talent points)",
"Eigene Schriften": "Custom fonts",
"Eigene Schriften werden beim Export mitgepackt. Achte darauf, dass die Lizenz der Schrift die Weitergabe in Spielen erlaubt.": "Custom fonts are packed into the export. Make sure the font’s license allows distribution in games.",
"Eigene Vorlage": "Custom template",
"Eigenen Punkten": "Custom points",
"Eigener Rahmen (PNG)": "Custom frame (PNG)",
"Eigener Ton": "Own sound",
"Eigenes": "Custom",
"Eigenes Effekt-Bild (statt Effekt)": "Own effect image (instead of effect)",
"Eigenes Schwarz-Weiß-Bild": "Custom black-and-white image",
"Eigenschaften": "Properties",
"Ein Bild wird automatisch zerschnitten und gemischt. Ohne eigenes Bild nimmt es den aktuellen Hintergrund.": "An image is automatically cut up and shuffled. Without a custom image it uses the current background.",
"Ein Dietrich könnte helfen.": "A lockpick might help.",
"Ein Gebäude erst nach einem gewonnenen Kampf freischalten.": "Unlock a building only after winning a battle.",
"Ein Gegner": "One enemy",
"Ein Haus kaufen, das danach als neuer Ort auf der Karte erscheint.": "Buy a house that then appears as a new place on the map.",
"Ein Händler, bei dem man einmalig eine Schatzkarte kaufen kann.": "A trader who sells a treasure map just once.",
"Ein Keyframe legt fest, wohin sich das Objekt bewegt, wenn der Spieler diesen Schritt erreicht. Die Kurve bestimmt, wie weich es dort ankommt.": "A keyframe sets where the object moves when the player reaches this step. The curve decides how smoothly it arrives.",
"Ein Ort, an dem der Spieler frei klickt. Bilder aus der Dateiliste auf die Bühne ziehen, um klickbare Objekte anzulegen.": "A place where the player clicks freely. Drag images from the file list onto the stage to create clickable objects.",
"Ein Projekt ist ein Ordner mit einer": "A project is a folder with a",
"Ein Stammgast lässt Trinkgeld da.": "A regular leaves a tip.",
"Ein Stift dreht sich im Schloss. Klicke (oder drücke Leertaste), wenn er im goldenen Bereich ist. Das Ergebnis landet in einer Variable.": "A pin rotates in the lock. Click (or press space) when it is in the golden zone. The result goes into a variable.",
"Ein Verbündeter": "One ally",
"Ein Ziel ist in 10 Stunden nicht erreichbar: Kosten, Produktion oder Freischaltung prüfen (ohne Klicken, ohne Skilltrees gerechnet).": "A goal can't be reached within 10 hours: check costs, production or unlocks (calculated without clicking and without skill trees).",
"Ein-/Ausblenden": "Fade in/out",
"Einblenden": "Fade in",
"Einblendung bei Änderung": "Notification on change",
"Einblendung zeigen (aus = Beziehungen bleiben geheim)": "Show notification (off = relationships stay secret)",
"Einblendungen im Spiel": "Notifications in the game",
"Eine Antwort, ein Hub-Objekt oder „Danach weiter zu“ auf diese Szene zeigen lassen.": "Point an answer, a hub object or “Then continue to” at this scene.",
"Eine Datei fehlt": "One file is missing",
"Eine Ebene kann einer Variable folgen: Hat die Variante einen passenden „Wert“, wird sie automatisch gewählt (z. B. Outfit = 2 → Rüstung).": "A layer can follow a variable: if the variant has a matching “value”, it is chosen automatically (e.g. outfit = 2 → armor).",
"Eine Ebene über den Figuren: Farbe oder Bild mit Mischmodus, Partikel (Regen, Schnee …), ein Filter wie „Rückblende“ oder Augen öffnen/schließen. Fertige Effekte findest du links unter „Effekte“.": "A layer above the characters: color or image with blend mode, particles (rain, snow …), a filter like “Flashback” or opening/closing eyes. Ready-made effects are on the left under “Effects”.",
"Eine Fähigkeit mit eigenem Ton spielt diesen statt der Standardtöne.": "An ability with its own sound plays it instead of the default sounds.",
"Eine Spalte = ein Klick des Spielers": "One column = one click of the player",
"Eine Story-Szene, die startet, wenn man an den Ort kommt und die Bedingungen passen. Pflicht-Ereignisse kommen zuerst (z. B. „Tag 5, morgens, Zuhause → Brief vom König“). Am Ende der Szene „Danach weiter zu“ leer lassen oder „↩ Zurück zum Ort“ wählen.": "A story scene that starts when you arrive at the location and the conditions match. Required events come first (e.g. “Day 5, morning, home → letter from the king”). At the end of the scene leave “Then continue to” empty or choose “↩ Back to the location”.",
"Eine Wiederholung spielt nur diese Szene und kehrt danach zur Galerie zurück. Spielstand und Werte bleiben unberührt.": "A replay only plays this scene and returns to the gallery afterwards. Save game and values stay untouched.",
"Eine lange Aufnahme mit vielen Sätzen? „Schneiden“ → „Teile erkennen“ → automatisch auf die Dialoge verteilen.": "A long recording with many sentences? “Cut” → “Detect parts” → distribute automatically to the dialogue lines.",
"Eine neuere Version dieses mitgelieferten Plugins ist da. Du hast die Datei selbst geändert – beim Einspielen gehen deine Änderungen verloren.": "A newer version of this bundled plugin is available. You changed the file yourself – installing it will discard your changes.",
"Eine „Nur wenn“-Bedingung verweist auf etwas, das es nicht mehr gibt – z. B. eine gelöschte Variable, Figur oder einen Gegenstand.": "An “Only if” condition refers to something that no longer exists – e.g. a deleted variable, character or item.",
"Einer Variable": "A variable",
"Einfach: Zutaten rein, fertig": "Simple: add ingredients, done",
"Einfügen": "Insert",
"Eingebaute Spur (kann nicht gelöscht werden)": "Built-in track (can’t be deleted)",
