"Erfolge": "Achievements",
"Erfolge schalten sich frei, wenn ihre Bedingung erfüllt ist (z. B. „Szene ‚Gutes Ende‘ gesehen“), oder per Aktion „🏆 Erfolg freischalten“. Sie gelten für alle Spielstände. Spieler sehen sie im Hauptmenü (Knopf mit Aktion „Erfolge“) und im Pausenmenü.": "Achievements unlock when their condition is met (e.g. “scene ‘Good ending’ seen”), or via the action “🏆 Unlock achievement”. They apply to all save games. Players see them in the main menu (button with action “Achievements”) and in the pause menu.",
"Erfolge öffnen": "Open achievements",
"Ergebnis": "Result",
