"Erledigt": "Completed",
"Erledigt! Klicken zum Weiterlesen.": "Done! Click to continue.",
"Erledigt, wenn": "Done when",
"Erledigt, wenn (ohne Abschnitte)": "Done when (without sections)",
"Erreicht die Beziehung den Wert, schickt die Figur eine Nachricht – auf Wunsch mit Bild. Das Bild landet in der Galerie bei dieser Figur und leuchtet dort als „Neu“, bis man es ansieht. Aussehen und Töne: Design → Spielsysteme → „Nachricht einer Figur“.": "When the relationship reaches the value, the character sends a message – with a picture if you like. The picture goes into the gallery under this character and glows as “New” until it's viewed. Look and sounds: Design → Game systems → “Message from a character”.",
"Erreicht, wenn": "Reached when",
"Erscheint, nachdem der Dialog dieses Schritts gelesen wurde. Ohne Ziel geht es in dieser Szene weiter.": "Appears after the dialogue line of this step has been read. Without a target the scene continues.",
"Erscheint, wenn eine Entscheidung die Zuneigung ändert: Name, Leiste vom alten zum neuen Wert, Pfeil mit Zahl und auf Wunsch das Porträt (aus der Figur oben). Stufenwechsel bekommen eine größere Einblendung.": "Appears when a decision changes affection: name, a bar from the old to the new value, an arrow with the number and, if you like, the portrait (from the character above). Stage changes get a bigger notification.",
"Erschrecken": "Startle",
"Ersetzt die Keyframes der betroffenen Knochen.": "Replaces the keyframes of the affected bones.",
"Erst aus, dann ein": "First off, then on",
"Erst baubar, wenn (optional)": "Only buildable when (optional)",
