"Fertige Bewegungen": "Ready-made movements",
"Fertige Bewegungen wie Laufen, Nicken, Winken oder Flügelschlag, Posen speichern und spiegeln, und Zwischensequenzen live einfügen oder als Video rendern.": "Ready-made movements like walking, nodding, waving or wing flaps, save and mirror poses, and insert cutscenes live or render them as video.",
"Fertige Dialoge als Text einfügen (auch Ren'Py)": "Insert finished dialogue as text (Ren'Py too)",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Bilder, Musik und Sprünge werden übersprungen.": "Insert finished dialogue: one line per sentence as “Name: Text”, lines without a name are narration. “> Answer” lines in a row become a choice, “# Title” starts a new scene. Ren'Py scripts are recognized (speaker codes from “define”, menu, label, jump); images and music are skipped.",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Sprünge (jump) werden zu Verbindungen, Bilder und Musik werden übersprungen.": "Insert finished dialogue: one line per sentence as “Name: Text”, lines without a name are narration. “> Answer” lines in a row become a choice, “# Title” starts a new scene. Ren'Py scripts are recognized (speaker codes from “define”, menu, label); jumps become connections, images and music are skipped.",
"Fertiges Spiel exportieren": "Export finished game",
