"Figuren bekommen ein Skelett, atmen, wehen – und du malst, was mitgeht.": "Characters get a skeleton, breathe, sway – and you paint what moves along.",
"Figuren bewegen (Keyframes)": "Moving characters (keyframes)",
"Figuren brauchen dafür Bones (Reiter „Figuren“ → „Bones & Blinzeln“).": "Characters need bones for this (tab “Characters” → “Bones & blinking”).",
"Figuren erst zeigen, wenn man sie getroffen hat": "Only show characters once they have been met",
"Figuren laufen, wachsen, drehen sich – mit weichen Kurven.": "Characters walk, grow, turn – with smooth curves.",
