"Freitag": "Friday",
"Fremd": "Stranger",
"Freund": "Friend",
"Früher musste man für einen Kauf zwei Dinge bauen: eine Bedingung „Geld ≥ 500“ und eine Aktion „Geld −500“. Das geht jetzt mit einem Feld: Preis.": "Before, a purchase needed two things: a condition “Money ≥ 500” and an action “Money −500”. Now one field does it: price.",
"Fundmeldung": "Item notification",
"Fundmeldung („Erhalten“)": "Item notification (“Received”)",
"Funken": "Sparks",
