"Fähigkeit fehlt": "Ability missing",
"Fähigkeiten": "Abilities",
"Färbt Figuren passend zum Hintergrund ein, damit sie nicht wie aufgeklebt wirken.": "Tints characters to match the background so they don’t look pasted on.",
"Füge im Reiter „Beziehungen“ Ray hinzu (Knopf „+ Ray“).": "Add Ray in the “Relationships” tab (button “+ Ray”).",
"Füge oben eine Sprache hinzu (z. B. „en“), dann erscheint daneben eine Spalte zum Übersetzen. Im Spiel kann man die Sprache oben umschalten.": "Add a language above (e.g. “en”), then a column for translating appears next to it. In the game the language can be switched at the top.",
"Füge rechts unter „Parallax“ eine zweite Ebene hinzu (+ Ebene) und wähle „Parallax Hügel“.": "Add a second layer on the right under “Parallax” (+ Layer) and choose “Parallax hills”.",
"Führt zu": "Leads to",
