"Für Beta-Tester und Modder: Taste ^ öffnet im fertigen Spiel die Entwickler-Konsole (Werte setzen, springen …).": "For beta testers and modders: the ^ key opens the developer console in the finished game (set values, jump …).",
"Für Sprecher:": "For voice actors:",
"Für jede Meldung: Position, Animation (auch Zersplittern), Dauer, Text mit Platzhaltern {quest} {reihe} {abschnitt} {figur}, Symbol, Sound oder Jingle. Farben, Rahmen und Hintergrund über „🎨“.": "For each message: position, animation (including shatter), duration, text with placeholders {quest} {reihe} {abschnitt} {figur}, icon, sound or jingle. Colors, frame and background via “🎨”.",
"Für {name} gibt es noch keine ♥-Punkte im Spiel. {levels} wird erst erreichbar, wenn du irgendwo Punkte vergibst.": "There are no ♥ points for {name} in the game yet. {levels} only becomes reachable once you give points somewhere.",
