"Gebäude produzieren Rohstoffe, werden ausgebaut, Ziele treiben die Geschichte voran. In Echtzeit, auch bei geschlossenem Spiel oder in Spielzeit. Mit Zeitvorschau.": "Buildings produce resources and get upgraded; goals move the story forward. In real time, also while the game is closed, or in game time. With a time preview.",
"Gebäude wird nirgends freigeschaltet": "Building is never unlocked",
"Gebäude „{name}“ soll durch eine Aktion freigeschaltet werden, aber das passiert nirgends.": "Building “{name}” should be unlocked by an action, but that never happens.",
