"Gegenstände": "items",
"Gegenstände ausrüsten: Kleidung, Werkzeug, Schmuck … Jeder Platz trägt einen Gegenstand. Der Spieler rüstet im Inventar aus (Gegenstand anklicken → „Ausrüsten“). Prüfen mit der Bedingung „👕 Trägt Gegenstand“, z. B. für Missionen, Quests oder wie eine Figur reagiert.": "Equip items: clothes, tools, jewellery … Each slot holds one item. The player equips in the inventory (click an item → “Equip”). Check it with the condition “👕 Wears item”, e.g. for missions, quests or how a character reacts.",
"Gegenstände im Kampf": "Items in battle",
"Gegenstände mit Haken „verschenkbar“ können Figuren gegeben werden (Aktion „🎁 Geschenk geben lassen“, z. B. an einem Hub-Objekt). Vorlieben legst du pro Kategorie fest, Sonderfälle pro Gegenstand. Der Spieler entdeckt die Vorlieben erst beim Schenken.": "Items ticked as “giftable” can be given to characters (action “🎁 Let player give a gift”, e.g. on a hub object). Set preferences per category, special cases per item. The player only discovers the preferences when giving gifts.",
"Gegenstände mit Platz": "Items with a slot",
"Gegenstände mit einer Wirkung erscheinen im Kampf unter „Gegenstände“ und werden beim Benutzen verbraucht.": "Items with an effect appear in battle under “Items” and are used up.",
"Gegenstände sammeln, Inventar-Menü mit Taste I.": "Collect items, inventory menu with key I.",
