"Gegner sollten nach rechts schauen": "Enemies should face right",
"Gegner stehen links und schauen nach rechts. Ohne Bild erscheint das Symbol.": "Enemies stand on the left and face right. Without an image the icon appears.",
"Geh zurück zur Lern-Szene, klicke die Auswahl an und gib der ersten Antwort ♥ Ray +10.": "Go back to the learning scene, click the choice and give the first answer ♥ Ray +10.",
"Geh zurück zur Szene „Lernen · Animations-Editor“, wähle Ray und stelle die neue Idle-Animation ein.": "Go back to the scene “Learn · Animation editor”, select Ray and set the new idle animation.",
