"Hafen": "Harbor",
"Haken setzen, was in die Galerie gehört. Bilder schalten sich frei, sobald sie im Spiel einmal zu sehen waren, Musik beim ersten Abspielen, Szenen beim ersten Besuch. Spieler öffnen die Galerie im Hauptmenü (Knopf mit Aktion „Galerie“) oder im Pausenmenü.": "Tick what belongs in the gallery. Images unlock as soon as they were seen once in the game, music when first played, scenes on the first visit. Players open the gallery in the main menu (button with action “Gallery”) or in the pause menu.",
