"Hier animierst du Figuren mit ihren Knochenpunkten: als Idle-Schleife (z. B. ungeduldig wippen), als Geste für einen Schritt (z. B. Winken) oder als ganze Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton. Zwischensequenzen laufen live im Spiel oder werden als Video gerendert.": "Here you animate characters with their bone points: as an idle loop (e.g. tapping impatiently), as a gesture for one step (e.g. waving) or as a whole cutscene with background, several characters, camera and sound. Cutscenes run live in the game or are rendered as video.",
"Hier bekommt eine Figur ein Skelett. Wähle ein Bild und eine Körper-Vorlage (Zweibeiner, Vierbeiner, Geflügelt …), dann bewegt sie sich weich.": "Here a character gets a skeleton. Choose an image and a body template (biped, quadruped, winged …), then it moves smoothly.",
"Hier fehlt noch Tiefe …": "Some depth is missing here …",
"Hier gestaltest du alles, was vorgefertigt ist: Sprechblasen, Buttons, Fenster, Schriften, Sounds und Mauszeiger.": "Here you design everything ready-made: speech bubbles, buttons, windows, fonts, sounds and mouse cursors.",
"Hier gibt es nichts mehr zu tun.": "There's nothing left to do here.",
"Hier ist nichts mehr.": "Nothing left here.",
"Hier kannst du gerade nicht arbeiten.": "You can’t work here right now.",
"Hier legst du Variablen, Gegenstände, Währungen und Loot-Tabellen an. Benutzt werden sie in den Szenen:": "Here you create variables, items, currencies and loot tables. They are used in the scenes:",
"Hier liegen alle Szenen deines Spiels. Story-Szenen laufen Schritt für Schritt ab, Hub-Szenen (weißer Punkt) sind Orte zum Herumklicken. Neue legst du mit „+ Story“ und „+ Hub“ an.": "All scenes of your game live here. Story scenes play step by step, hub scenes (white dot) are places to click around. Create new ones with “+ Story” and “+ Hub”.",
"Hilfe": "Help",
"Hilfe und Tour": "Help and tour",
"Hilfe-Prüfung": "Help check",
"Hintergrund": "Background",
"Hintergrund (Platzhalter, wenn leer)": "Background (placeholder if empty)",
"Hintergrund (auf einen Hintergrund-Clip ziehen)": "Background (drag onto a background clip)",
