"Hintergrund ohne Bild – rechts eins wählen": "Background without image – choose one on the right",
"Hintergrund zieht schnell endlos vorbei, leichtes Rütteln": "Background rushes by endlessly, slight shaking",
"Hintergrund ·": "Background ·",
"Hintergrund, Musik, Titel oder Logo und das Aussehen der Buttons. Im Reiter „Design“ kannst du den Buttons eigene Bilder geben.": "Background, music, title or logo and the look of the buttons. In the “Design” tab you can give the buttons custom images.",
"Hintergrund-Spur": "Background track",
"Hintergrundbild rechts wählen": "Choose a background image on the right",
"Hintergründe automatisch an die Tageszeit anpassen (wenn beim Hintergrund keine eigene Tageszeit gewählt ist)": "Adjust backgrounds to the time of day automatically (if the background has no time of day of its own)",
"Hinweis": "Hint",
"Hinweis: Das Skelett gehört zum Bild. Ein neues Bild braucht eigene Bones.": "Note: the skeleton belongs to the image. A new image needs its own bones.",
