"Hub-Szene": "Hub scene",
"Hub-Szene öffnen und ein Objekt anlegen (z. B. eine Tür).": "Open a hub scene and add an object (e.g. a door).",
"Hub-Szene öffnen, Objekt anklicken.": "Open the hub scene and click the object.",
"Hub-Szenen werden zu Orten, zwischen denen man frei reisen kann – über die Weltkarte (Taste M) und den Knopf „🏠 Zuhause“ (Taste H). Story-Szenen werden zu Ereignissen: Sie starten, wenn man zur passenden Zeit an einen Ort kommt, und kehren danach dorthin zurück. Mit der Aktion „Freie Zeit beginnt / endet“ wechselst du zwischen freiem Herumlaufen und linearer Story.": "Hub scenes become locations you can travel between freely – via the world map (key M) and the “🏠 Home” button (key H). Story scenes become events: they start when you come to a location at the right time and return there afterwards. With the action “Free time begins / ends” you switch between free roaming and linear story.",
"Huf": "Hoof",
"Hängt an": "Attached to",
"Höchste Stufe": "Maximum level",
"Höchste Stufe erreicht": "Highest stage reached",
