"Idle (Schleife)": "Idle (loop)",
"Idle-Animation (Dauer-Schleife)": "Idle animation (continuous loop)",
"Idle-Schleifen und Gesten mit Knochen – oder ganze Zwischensequenzen.": "Idle loops and gestures with bones – or whole cutscenes.",
"Im Inventar erscheint „Benutzen“, sobald hier mindestens eine Aktion steht (z. B. Heiltrank: Leben + 20). Für „Schlüssel auf Tür“ stellst du das am Hub-Objekt ein (Abschnitt „Gegenstand benutzen“).": "“Use” appears in the inventory as soon as there is at least one action here (e.g. healing potion: life + 20). For “key on door” set this on the hub object (section “Use item”).",
"Im Inventar „Benutzen“ anbieten": "Offer “Use” in the inventory",
"Im Inventar: Gegenstand wählen → „Kombinieren …“ → zweiten anklicken. Z. B. Seil + Haken → Enterhaken.": "In the inventory: choose an item → “Combine …” → click the second one. E.g. rope + hook → grappling hook.",
"Im Pausenmenü": "In the pause menu",
"Im Pausenmenü (Esc) anzeigen": "Show in the pause menu (Esc)",
"Im Pfade-Plan zeigen": "Show in the paths view",
"Im Spiel": "In game",
"Im Spiel: Inventar → Gegenstand → „Benutzen“ → auf das Objekt klicken. Falscher Gegenstand: „Das funktioniert hier nicht.“": "In the game: inventory → item → “Use” → click the object. Wrong item: “That doesn’t work here.”",
"Im ganzen Spiel gibt es bisher {pts} ♥-Punkte für {name} (zusammen mit dem Startwert höchstens {max} %). Für {levels} fehlen noch {miss} Punkte.": "So far the whole game gives {pts} ♥ points for {name} (at most {max} % including the start value). {levels} still needs {miss} more points.",
"Im letzten Schritt liegen noch Clips.": "There are still clips in the last step.",
