"In aktuelle Szene einfügen": "Insert into current scene",
"In den Pfaden zeigen": "Show in paths",
"In diesem Ordner liegt schon ein Projekt. Überschreiben?": "There is already a project in this folder. Overwrite?",
"In dieser Fassung ist die Update-Suche nicht eingerichtet (Entwicklungsversion oder ohne GitHub-Adresse).": "Update checks aren't set up in this version (development build or no GitHub address).",
