"Inventar öffnen": "Open inventory",
"Inventar-Design öffnen": "Open inventory design",
"Inventar-Menü": "Inventory menu",
"Inventar-Titel": "Inventory title",
"Inventar-Vorschau ansehen →": "See inventory preview →",
"Inventar:": "Inventory:",
"Irgendwo im Keller liegt der Schlüssel zur Schatzkammer.": "Somewhere in the cellar lies the key to the treasury.",
"Ist es eine Szene, die du nur zum Testen angelegt hast, kannst du die Meldung ausblenden.": "If it's a scene you only made for testing, you can hide the message.",
"Ja": "Yes",
"Ja (Rechtsklick dreht)": "Yes (right-click rotates)",
"Jalousie": "Blinds",
"Je besser gespielt, desto mehr Lohn (40–100 %) und Erfahrung.": "The better you play, the more pay (40–100 %) and experience.",
"Jede Hub-Szene kann ein Ort sein. „Per Aktion“ heißt: erst nach der Aktion „📍 Ort freischalten“ (z. B. am Ende von Kapitel 1).": "Every hub scene can be a location. “Via action” means: only after the action “📍 Unlock location” (e.g. at the end of chapter 1).",
"Jede Plugin-Aktion erscheint danach überall unter „+ Aktion“. Bild-Parameter lassen sich im Editor austauschen.": "Every plugin action then appears everywhere under “+ Action”. Image parameters can be swapped in the editor.",
"Jede Spalte ist ein Klick des Spielers. Clips verschieben, am rechten Rand ziehen zum Verlängern, Doppelklick auf eine Spur legt einen neuen Clip an.": "Each column is one click of the player. Move clips, drag the right edge to extend, double-click a track to create a new clip.",
"Jede Spalte ist ein Schritt, also ein Klick des Spielers.": "Each column is a step, i.e. one click of the player.",
"Jede Zeile ist ein Knochen. Rauten verschieben ändert das Timing, Rechtsklick löscht. Oben im Lineal ziehst du die Abspielposition.": "Each row is a bone. Moving diamonds changes the timing, right-click deletes. Drag the playhead in the ruler at the top.",
"Jeder Status": "Any status",
"Jeder Text hat eine feste ID. Die Timeline verweist nur darauf, deshalb übersetzt du hier alles an einem Ort.": "Every text has a fixed ID. The timeline only refers to it, so you translate everything here in one place.",
"Jedes Thema ist eine kleine Szene im Lernprojekt. Rechts unten stehen die Aufgaben – das Programm hakt sie selbst ab, sobald du sie erledigt hast. Dein eigenes Projekt bleibt unberührt.": "Each topic is a small scene in the learning project. The tasks are at the bottom right – the program checks them off by itself as soon as you’ve done them. Your own project stays untouched.",
"Jedes Öffnen würfelt neu. Wer vorher speichert und zurücklädt, kann bessere Beute erzwingen.": "Every opening rolls anew. Saving before and reloading lets players force better loot.",
"Jetzt": "Now",
