"Kampf wie in klassischen Rollenspielen: rundenbasiert, Seitenansicht, Gruppe aus bis zu vier Helden. Gestartet wird ein Kampf mit der Aktion „⚔ Kampf starten“ – an einem Dialog, einer Antwort oder einem Hub-Objekt. Sieg, Niederlage und Flucht führen in eigene Szenen; „⚔ Kampf gewonnen“ fragt das Ergebnis später ab.": "Combat like in classic RPGs: turn-based, side view, a party of up to four heroes. A battle starts with the action “⚔ Start battle” – on a dialogue line, an answer or a hub object. Victory, defeat and escape lead to their own scenes; “⚔ Battle won” checks the result later.",
