"Sechs Minispiele mit Ergebnis (0–100 % oder geschafft/nicht geschafft): Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter.": "Six minigames with a result (0–100 % or success/failure): click reflex, memory, puzzle, cooking & brewing, coin toss, petals.",
"Sechs Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "Six minigames. Start them via “+ Action” → “Minigames: …” – in an answer, on a hub object, in a dialogue line or as a job’s minigame. Choose settings and images directly on the action. Every game returns a result of 0–100 % (field “Result into” → variable).",
"Sieben Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "Seven minigames. Start them via “+ Action” → “Minigames: …” – in an answer, on a hub object, in a dialogue line or as a job’s minigame. Choose settings and images directly on the action. Every game returns a result of 0–100 % (field “Result into” → variable).",
"Sechs fertige Sprechblasen zum Start. Danach lässt sich jede Farbe ändern, ein eigener PNG-Rahmen einsetzen und alles als eigene Vorlage speichern.": "Six ready-made speech bubbles to start with. Afterwards you can change every color, use a custom PNG frame and save everything as your own template.",
