"Tipp für den Spieler (optional)": "Tip for the player (optional)",
"Tipp:": "Tip:",
"Tipp: Auf gebaute Gebäude klicken bringt sofort etwas.": "Tip: clicking built buildings yields something right away.",
"Tipp: Beim Testen öffnet die Taste ^ (oder F12) die Entwickler-Konsole mit echten Bildern pro Sekunde.": "Tip: when testing, the ^ key (or F12) opens the developer console with real frames per second.",
"Tipp: Das Rechteck darf etwas größer als der geschlossene Mund sein. Es öffnet sich von oben nach unten.": "Tip: the rectangle may be a bit larger than the closed mouth. It opens from top to bottom.",
"Tipp: Eine Antwort „Schlafen gehen“ mit der Aktion „Zeit vergehen lassen → nächster Tag“ und Hub-Objekte mit der Bedingung „Tageszeit ist Abend“ – fertig ist ein Tagesablauf.": "Tip: an answer “Go to sleep” with the action “Let time pass → next day” and hub objects with the condition “time of day is evening” – and you have a daily routine.",
"Tipp: Figuren lassen sich auf der Bühne auch direkt ziehen – waagerecht für die Position, senkrecht für die Höhe (Umschalt: nur eine Richtung).": "Tip: you can also drag characters directly on the stage – horizontally for the position, vertically for the height (Shift: one direction only).",
"Tipp: Mit dem Setup (VN-Timeline-Engine-Setup.exe) kommen Updates automatisch und laden nur die Änderungen. Deine Projekte bleiben dabei, wo sie sind.": "Tip: With the setup (VN-Timeline-Engine-Setup.exe), updates arrive automatically and only download what changed. Your projects stay where they are.",
"Tipp: Mit „100× simulieren“ siehst du, wie schwer der Kampf ist.": "Tip: “Simulate 100×” shows how hard the battle is.",
"Tipp: Schreibt der Held seine Stufe in eine Variable, kann ein Skilltree bei jedem Stufenaufstieg Punkte geben.": "Tip: If the hero writes their level into a variable, a skill tree can give points on every level-up.",
"Tipp: So kannst du z. B. Vorschau-Töne über Kopfhörer hören und das Test-Spiel über die Boxen. Spieler stellen ihr Gerät im fertigen Spiel unter Einstellungen → Tonausgabe selbst ein.": "Tip: this way you can hear preview sounds on headphones and the test game on speakers. Players choose their device in the finished game under Settings → Sound output.",
