"Zieh ein Rechteck um den Mund der Figur.": "Drag a rectangle around the character’s mouth.",
"Zieh im Bild ein Rechteck um den Mund. Im Spiel öffnet und schließt er sich dann nach der Lautstärke der Sprachaufnahme. Ohne Aufnahme bewegt er sich, solange der Text getippt wird.": "Drag a rectangle around the mouth in the image. In the game it then opens and closes with the volume of the voice recording. Without a recording it moves while the text is being typed.",
