"“: Unterkarte fehlt": "”: submap missing",
"„+ Neues Plugin“ legt eine Vorlage an, „Code bearbeiten“ öffnet den eingebauten Editor. Die Anleitung steht in PLUGINS.md.": "“+ New plugin” creates a template, “Edit code” opens the built-in editor. The guide is in PLUGINS.md.",
"„Auf Preis umstellen“ drücken – Bedingung und Geld-Aktion werden durch den Preis ersetzt.": "Press “Switch to price” – the condition and the money action are replaced by the price.",
"„Fortsetzen“ lädt den neuesten Spielstand und ist ausgegraut, solange es keinen gibt. „Beenden“ schließt das fertige Spiel, beim Testen geht es zurück zum Editor.": "“Continue” loads the latest save and is grayed out as long as there is none. “Quit” closes the finished game; when testing it returns to the editor.",
"„Liebt mich, liebt mich nicht“ – die Blattzahl sorgt für ein echtes 50:50.": "“Loves me, loves me not” – the petal count makes for a true 50:50.",
"„Menü testen“ zeigt das Menü so, wie es der Spieler sieht.": "“Test menu” shows the menu exactly as the player sees it.",
"„Neu“ zeigen als": "Show “New” as",
"„Szene testen“ spielt die offene Szene ab dem gewählten Schritt. „Spiel testen“ startet alles mit Hauptmenü, genau wie später beim Spieler.": "“Test scene” plays the open scene from the chosen step. “Test game” starts everything with the main menu, just like for the player later.",
"„{name}“ ist ein Ausrüstungs-Gegenstand. Zum Anziehen besser „👕 Trägt Gegenstand“ nehmen – „benutzt“ heißt: im Inventar auf „Benutzen“ geklickt.": "“{name}” is an equipment item. For putting it on, better use “👕 Wears item” – “used” means: clicked “Use” in the inventory.",
