"Zum Beispiel „✔ Spieler hat … eine Szene gesehen“ oder eine Variable, die ein Dialog setzt. Danach läuft der Aufbau dauerhaft.": "For example “✔ Player has … seen a scene” or a variable that a dialogue sets. After that building keeps running.",
