" (Gliederpuppe)": " (jointed puppet)",
"+ Gliederpuppe": "+ Jointed puppet",
"+ Neue Gliederpuppe": "+ New jointed puppet",
"1. Körperteile als einzelne PNGs vorbereiten (transparent). 2. Puppe anlegen und die Bilder auf die Fläche ziehen. 3. Bei jedem Teil den roten Pin auf das Gelenk ziehen und auf dem Eltern-Teil loslassen (Unterarm-Pin auf den Oberarm, Oberarm-Pin auf den Torso). 4. Im Animations-Editor einen Darsteller anlegen und „Gliederpuppe“ wählen.": "1. Prepare body parts as separate PNGs (transparent). 2. Create a puppet and drag the images onto the board. 3. For every part, drag the red pin onto the joint and release it over the parent part (forearm pin onto the upper arm, upper arm pin onto the torso). 4. In the animation editor add an actor and choose “Jointed puppet”.",
"Animation (Bones)": "Animation (bones)",
"Animation (Gliederpuppe)": "Animation (jointed puppet)",
"Ausprobieren: Teil ziehen = um den Pin drehen · Umschalt + ziehen = IK (die Kette folgt der Maus) · Wurzel-Teil ziehen = ganze Figur verschieben. Nichts davon wird gespeichert.": "Try out: drag a part = rotate around its pin · Shift + drag = IK (the chain follows the mouse) · drag the root part = move the whole figure. Nothing of this is saved.",
"Bild als neues Teil hinzufügen": "Add image as a new part",
"Bilder aus der Dateiliste hierher ziehen = neues Teil · Teil ziehen = verschieben (Kinder wandern mit, Alt = nur dieses Teil) · roten Pin ziehen = Gelenk setzen; auf einem anderen Teil loslassen = daran anhängen · Entf = Teil löschen": "Drag images from the file list here = new part · drag a part = move (children follow, Alt = only this part) · drag the red pin = set the joint; release over another part = attach to it · Del = delete part",
"Bilder aus der Dateiliste hierher ziehen – jedes Bild wird ein Körperteil.": "Drag images from the file list here – every image becomes a body part.",
"Bones": "Bones",
"Bones benutzen (Verformen, Atmen, Physik aus dem Bones-Editor)": "Use bones (deforming, breathing, physics from the bones editor)",
"Bones dieses Teils": "Bones of this part",
"Die Engine verfolgt alle Wege ab der Startszene. Orte der Weltkarte zählen als erreichbar (man reist hin), ebenso alles, was von dort aus weitergeht. Kommt sie trotzdem nirgends bei dieser Szene an, erscheint die Meldung.": "The engine follows every path from the start scene. Locations on the world map count as reachable (you travel there), as does everything that continues from there. If it still never arrives at this scene, this message appears.",
"Diese Figur hat noch keine Bones. ": "This character has no bones yet. ",
"Dieses Teil hat noch keine Bones. Mit Bones lässt es sich zusätzlich verformen – z. B. Haare, Schwanz, Umhang mit Physik.": "This part has no bones yet. With bones it can also be deformed – e.g. hair, tail, cape with physics.",
"Drehung in Ruhe °": "Rest rotation °",
"Ebenen-Figuren (Körper, Gesicht, Outfit) und Gliederpuppen (Körperteile mit Gelenken) legst du oben unter „Figuren“ an.": "Layered characters (body, face, outfit) and jointed puppets (body parts with joints) are created above under “Characters”.",
"Figuren brauchen dafür Bones (Reiter „Figuren“ → „Bones & Blinzeln“) – oder du nimmst eine Gliederpuppe aus Körperteilen (Reiter „Figuren“ → „Gliederpuppen“).": "Characters need bones for this (tab “Characters” → “Bones & blinking”) – or use a jointed puppet made of body parts (tab “Characters” → “Jointed puppets”).",
"Gliederpuppe": "Jointed puppet",
"Gliederpuppe löschen": "Delete jointed puppet",
"Gliederpuppen": "Jointed puppets",
"Hängt an (Eltern-Teil)": "Attached to (parent part)",
"Idle": "Idle",
"Idle abspielen": "Play idle",
"Idle dieses Teils": "Idle of this part",
"Idle · ": "Idle · ",
"Idle-Bewegung und Gesten kommen aus dem Animations-Editor (Darsteller = diese Gliederpuppe).": "Idle motion and gestures come from the animation editor (actor = this jointed puppet).",
"Jiggle schwingt nach, wenn sich das Eltern-Teil bewegt (Haare, Ohren, Schwanz). Unterschiedlicher Versatz bei mehreren Teilen wirkt lebendiger.": "Jiggle swings after the parent part moves (hair, ears, tail). Different offsets on several parts look more alive.",
"Keine Antwort, kein „Danach weiter zu“, kein Hub-Objekt, kein Hub-Dialog, keine Reise und keine Aktion führt zu dieser Szene. Spieler sehen sie nie.": "No answer, no “Then continue to”, no hub object, no hub dialogue, no travel and no action leads to this scene. Players never see it.",
"Lösen": "Release",
"Name": "Name",
"Neue Gliederpuppe": "New jointed puppet",
"Pin X (im Bild)": "Pin X (in image)",
"Pin Y (im Bild)": "Pin Y (in image)",
"Pins": "Pins",
"Puppe": "Puppet",
"Puppenspiel: Teil oder Endpunkt ziehen = um den Pin drehen · Umschalt + ziehen = IK (Kette folgt der Maus) · Pfeile (rot X, grün Y, gelb frei) = ganze Figur verschieben · Doppelklick auf ein Teil = festpinnen (bleibt an Ort und Stelle, wenn sich der Körper bewegt).": "Puppeteering: drag a part or its end point = rotate around the pin · Shift + drag = IK (chain follows the mouse) · arrows (red X, green Y, yellow free) = move the whole figure · double-click a part = pin it (it stays in place when the body moves).",
"Setze eine Figur aus einzelnen Körperteilen zusammen – Kopf, Torso, Oberarm, Unterarm, Hand … – jedes Teil ein eigenes Bild mit transparentem Hintergrund. Verbinde die Teile mit Gelenk-Pins: Der Oberarm hängt an der Schulter, der Unterarm am Ellbogen. Dann lässt sich die Figur wie eine Puppe bewegen, im Animations-Editor animieren und im Spiel mit Idle-Bewegungen zeigen.": "Build a character from separate body parts – head, torso, upper arm, forearm, hand … – each part its own image with a transparent background. Connect the parts with joint pins: the upper arm hangs on the shoulder, the forearm on the elbow. Then the character moves like a puppet, can be animated in the animation editor and shows idle motion in the game.",
"Spiegelt das Teil und seine Kinder an der Mitte der Puppe – z. B. linken Arm als rechten Arm anlegen": "Mirrors the part and its children at the centre of the puppet – e.g. create the right arm from the left arm",
"Stärke °": "Strength °",
"Szene „{name}“ wird nirgends betreten – kein Weg vom Start, keine Reise, kein Objekt, keine Aktion führt dorthin.": "Scene “{name}” is never entered – no path from the start, no travel, no object, no action leads there.",
"Teil": "Part",
"Teil auf der Fläche anklicken. Der rote Punkt ist sein Gelenk-Pin: auf das Gelenk ziehen und über dem Teil loslassen, an dem es hängen soll.": "Click a part on the board. The red dot is its joint pin: drag it onto the joint and release it over the part it should hang on.",
