"Führt im Spiel die Aktionen aus.": "Runs the actions in the game.",
"Ein Handy oder ein Computer im Spiel: Startbildschirm mit Apps wie Nachrichten, Inventar, Beziehungen, Galerie, Quests oder eigenen Apps (Seiten, Aktionen, Sprung in eine Szene). Öffnen per Knopf, Taste oder mit der Aktion „📱 Gerät öffnen“ – z. B. auf einer Hitbox im Hub (der Laptop auf dem Schreibtisch).": "A phone or a computer inside the game: a home screen with apps such as messages, inventory, relationships, gallery, quests or your own apps (pages, actions, jump to a scene). Open it with a button, a key or the action “📱 Open device” – e.g. on a hitbox in the hub (the laptop on the desk).",
