"Reihenfolge wie auf dem Gerät. Symbol: Emoji oder eigenes Bild. Mit 🔒 erscheint eine App erst, wenn ihre Bedingungen erfüllt sind.": "Same order as on the device. Icon: emoji or your own image. With 🔒 an app only appears once its conditions are met.",
