"System aus": "system off",
"Im Spiel öffnen": "Opening it in the game",
"Knopf oben rechts, Taste oder Pausenmenü (siehe „Gerät“). In der Story oder im Hub: Aktion „📱 Gerät öffnen“, z. B. an einem Hub-Objekt (Hitbox) – optional direkt in einer App oder einem Chat. Eingebaute Apps öffnen ihren Bildschirm und kehren danach zum Gerät zurück.": "Button at the top right, key or pause menu (see “Device”). In the story or hub: action “📱 Open device”, e.g. on a hub object (hitbox) – optionally straight into an app or a chat. Built-in apps open their screen and return to the device afterwards.",
"Zu den Nachrichten →": "To the messages →",
"Vorschau (klickbar)": "Preview (clickable)",
"In der Vorschau sind alle Unterhaltungen schon angekommen. Eingebaute Apps und Aktionen laufen erst im Spiel.": "In the preview every conversation has already arrived. Built-in apps and actions only run in the game.",
"Eine eigene App zeigt eine Seite (z. B. Notizen, eine E-Mail, eine Webseite, ein Foto) und/oder führt Aktionen aus. Mit „➜ Zu Szene oder Hub wechseln“ schließt sich das Gerät und die Szene startet.": "An own app shows a page (e.g. notes, an e-mail, a website, a photo) and/or runs actions. With “➜ Go to scene or hub” the device closes and the scene starts.",
"Titel der Seite": "Page title",
"Beim Öffnen ausführen": "Run when opened",
"Chats bleiben über alle Szenen erhalten. Eine Unterhaltung kommt automatisch an (sobald ihre Bedingungen stimmen) oder per Aktion „💬 Nachricht schicken“. Zeilen mit 🔒 kommen nur, wenn ihre Bedingungen erfüllt sind – so bekommt jede Route ihre eigene Version. Antworten wählt der Spieler; sie können Aktionen ausführen und zur nächsten Unterhaltung führen.": "Chats are kept across all scenes. A conversation arrives automatically (as soon as its conditions are met) or with the action “💬 Send message”. Lines with 🔒 only arrive when their conditions are met – so every route gets its own version. The player picks the replies; they can run actions and lead to the next conversation.",
"Kein Gerät hat die App „Nachrichten“. Unter „Geräte“ hinzufügen.": "No device has the “Messages” app. Add it under “Devices”.",
"Meldung bei neuer Nachricht (Klick öffnet den Chat)": "Notification for new messages (click opens the chat)",
"Ton bei neuer Nachricht": "Sound for new messages",
"— wie Beziehungs-Meldung —": "— like relationship notification —",
