"Pixel-Art: Größe wählen und „+ Neues Sprite“. Dann Bild für Bild zeichnen und animieren – fertige Animationen landen als Bild bei den Dateien und laufen in Szenen, Hubs und im Kampf.": "Pixel art: pick a size and “+ New sprite”. Then draw and animate frame by frame – finished animations go to your files as an image and play in scenes, hubs and battles.",
