"Neue Farbe zur Palette": "New colour to palette",
"Linke Maustaste = malen · rechte = radieren · Strg + Mausrad = Zoom. Ändert man eine Farbe, ändert sie sich in allen Bildern.": "Left mouse = paint · right = erase · Ctrl + wheel = zoom. Changing a colour changes it in every frame.",
