"Als animiertes Bild ins Projekt": "Add to project as animated image",
"Sprite-Sheet (alle Animationen) ins Projekt": "Sprite sheet (all animations) to project",
"Jede Animation wird ein eigenes animiertes Bild bei den Dateien – nutzbar als Figur, Hintergrund, Hub-Objekt oder Kämpfer. Nach Änderungen „aktualisieren“: Alle Stellen, die das Bild nutzen, zeigen dann die neue Fassung.": "Each animation becomes its own animated image in your files – usable as a character, background, hub object or fighter. After changes, “update”: every place that uses the image then shows the new version.",
