"Ton bei Gewinn": "Sound on win",
"Die Spiele startest du mit den Aktionen „Spielhalle: Dart“, „Spielhalle: Billard“ und „Spielhalle: Spielautomat“ – z. B. an einem Hub-Objekt (Dartscheibe in der Taverne) oder in einer Antwort. Wie bei allen Minispielen kannst du dort eine Szene für Sieg und Niederlage wählen.": "Start the games with the actions “Arcade: Darts”, “Arcade: Pool” and “Arcade: Slot machine” – e.g. on a hub object (dartboard in the tavern) or in an answer. As with all minigames you can pick a scene for winning and losing there.",
"🤖 Gegner": "🤖 Opponents",
"🎰 Spielautomaten": "🎰 Slot machines",
"🎯 Dart & Billard": "🎯 Darts & pool",
"🎯 Dart": "🎯 Darts",
"🎱 Billard": "🎱 Pool",
"Das Fadenkreuz schwebt über die Scheibe – im richtigen Moment klicken. Spielarten: 301 oder 501 (von oben auf 0, auf Wunsch mit einem Doppel zum Schluss) oder „höchste Punktzahl nach X Runden“. Mit Gegner abwechselnd je 3 Pfeile, allein gegen eine Punktzahl. Scheibe, Pfeil, Fadenkreuz und Hintergrund lassen sich durch eigene Bilder ersetzen (an der Aktion oder als Standard unter Design → Spielsysteme). Bei einer eigenen Scheibe gibst du an, wie groß der Doppel-Ring im Bild ist – danach wird gezählt.": "The crosshair floats over the board – click at the right moment. Game types: 301 or 501 (count down to 0, optionally finishing on a double) or “highest score after X rounds”. Against an opponent you take turns with 3 darts each, alone you play for a target score. Board, dart, crosshair and background can be replaced with your own images (on the action or as the default under Design → Game systems). For your own board, enter how big the double ring is in the image – scoring follows it.",
"Dart allein ausprobieren": "Try darts alone",
"Mit der Maus zielen, Maustaste drücken = anlegen, zurückziehen und nach vorn schwingen = stoßen. Je schneller der Schwung, desto härter der Stoß (Loslassen stößt mit der Kraft des Zurückziehens). Spielarten: 8-Ball (Volle/Halbe, zum Schluss die 8) oder „wer mehr Kugeln versenkt“. Tisch, Tuch, Queue und jede Kugel lassen sich gestalten – Kugeln 1–15 als Standard unter Design → Spielsysteme → Billard.": "Aim with the mouse, press the button = set up, pull back and swing forward = shoot. The faster the swing, the harder the shot (releasing shoots with the strength of the pull). Game types: 8-ball (solids/stripes, the 8 last) or “whoever pots more balls”. Table, cloth, cue and every ball can be designed – balls 1–15 as defaults under Design → Game systems → Pool.",
"Billard allein ausprobieren": "Try pool alone",
"Kugeln und Tisch gestalten": "Design balls and table",
