"Tresor mit Drehrad, Tastenfeld oder Zahlenschloss mit Rädchen. Der Code kann fest sein, aus einer Variable kommen (dann findet man ihn in der Geschichte) oder zufällig – auch zufällig in eine Variable, die du später im Text zeigst.": "Safe with a dial, keypad or combination lock with wheels. The code can be fixed, come from a variable (so it can be found in the story) or be random – also random into a variable that you show later in the text.",
"Art, Code, Zahlen auf dem Rad, Hilfe (Klicken abhören oder Farben), Versuche, Zeitlimit, Hilfs-Gegenstand, Bilder für Tür, Rad und Inhalt": "Type, code, numbers on the dial, help (listen for clicks or colours), attempts, time limit, helper item, images for door, dial and contents",
"Teile drehen, bis die Leitung von links nach rechts durchgeht – als Rohre mit Wasser, Kabel mit Strom oder magische Runen. Jedes Feld ist zufällig und immer lösbar.": "Turn pieces until the line runs from left to right – as water pipes, power cables or magic runes. Every board is random and always solvable.",
"Größe, Aussehen, Zeitdruck, Drehungen, eigene Bilder für die Teile": "Size, look, time pressure, turns, your own images for the pieces",
"Neun Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "Nine minigames. Start them with “+ Action” → “Minigames: …” – in an answer, on a hub object, in a dialogue or as a job’s minigame. Settings and images are chosen right on the action. Every game returns a result of 0–100 % (field “Result in” → variable).",
