"Die Spiele startest du mit den Aktionen „Spielhalle: Dart“, „Spielhalle: Billard“, „Spielhalle: Blackjack“ und „Spielhalle: Spielautomat“ – z. B. an einem Hub-Objekt (Dartscheibe in der Taverne) oder in einer Antwort. Wie bei allen Minispielen kannst du dort eine Szene für Sieg und Niederlage wählen.": "Start the games with the actions “Arcade: Darts”, “Arcade: Pool”, “Arcade: Blackjack” and “Arcade: Slot machine” – e.g. on a hub object (dartboard in the tavern) or in an answer. As with all minigames you can pick a scene for winning and losing there.",
"🎲 Dart, Billard, Blackjack": "🎲 Darts, pool, blackjack",
"🃏 Blackjack": "🃏 Blackjack",
"Näher an 21 als der Croupier, ohne drüber zu kommen. Ziehen, Stehen, Verdoppeln und Teilen; Blackjack zahlt 3:2 (oder 6:5). Einsatz in einer Währung deines Spiels oder mit Spielgeld. Als Croupier kannst du einen Gegner wählen – dann erscheinen sein Name, Bild und seine Sprüche. Mit „Tipps“ (oder einem Gegenstand bzw. Perk) zeigt das Spiel den besten Zug nach der Grundstrategie.": "Get closer to 21 than the dealer without going over. Hit, stand, double and split; blackjack pays 3:2 (or 6:5). Bets in a currency of your game or with play money. You can pick an opponent as dealer – their name, image and lines then appear. With “Tips” (or an item or perk) the game shows the best move by basic strategy.",
