"Import abgebrochen – es wurde nichts gespeichert.": "Import cancelled – nothing was saved.",
"Ein Social Media im Spiel: Kontakte posten Beiträge mit Text und Bild, andere Figuren liken und kommentieren. Ein Beitrag erscheint automatisch, sobald seine Bedingungen stimmen, oder nur per Aktion „📸 Beitrag posten“ (z. B. nach einer Entscheidung, an einem Ort oder nach einem Minispiel). Der Spieler kann liken und mit vorbereiteten Antworten kommentieren.": "A social network inside your game: contacts post text and pictures, other characters like and comment. A post appears automatically as soon as its conditions are met, or only through the action “📸 Post” (e.g. after a decision, at a location or after a minigame). The player can like posts and comment with prepared replies.",
"Noch kein Gerät hat die App „Social Media“.": "No device has the “Social media” app yet.",
