"App „Social Media“ auch auf:": "Also add the “Social media” app to:",
"Neu hier? Social Media in 4 Schritten": "New here? Social media in 4 steps",
"1. Unter „Nachrichten“ Kontakte anlegen (die Autoren). 2. Die App einem Handy oder Computer geben. 3. Hier Beiträge schreiben. 4. Festlegen, wann sie erscheinen. Im Text werden @Name und #Thema automatisch zu Links. Mehr mit 💡.": "1. Create contacts under “Messages” (the authors). 2. Give the app to a phone or computer. 3. Write posts here. 4. Decide when they appear. In the text, @Name and #topic automatically become links. More with 💡.",
"Social Media – so geht’s": "Social media – how it works",
"Eine App für Handy oder Computer im Spiel, in der deine Figuren Beiträge posten – wie Instagram oder Twitter, nur mit deinen Figuren. Beiträge haben Text, Bild, Likes und Kommentare. Der Spieler kann liken, kommentieren und Profile ansehen.": "An app for the in-game phone or computer where your characters post – like Instagram or Twitter, just with your characters. Posts have text, a picture, likes and comments. The player can like, comment and view profiles.",
"Wofür ist das gut?": "What is it good for?",
"Die Spielwelt wirkt lebendig: Figuren reagieren auf das, was der Spieler tut. Ein Beitrag kann ein Hinweis sein, eine Belohnung, ein Stimmungsbild – oder ein Geheimnis, das später wieder gelöscht wird.": "The game world feels alive: characters react to what the player does. A post can be a clue, a reward, a mood – or a secret that gets deleted later.",
"So legst du los": "How to get started",
"Spielsysteme → Nachrichten: Kontakte anlegen (am besten aus deinen Figuren – dann stimmt das Profilbild).": "Game systems → Messages: create contacts (ideally from your characters – then the profile picture matches).",
"Spielsysteme → Geräte: dem Handy oder Computer die App „Social Media“ geben (oder oben auf „Zu … hinzufügen“ klicken).": "Game systems → Devices: give the phone or computer the “Social media” app (or click “Add to …” above).",
"Hier unter „Beiträge“ auf „+ Beitrag“ klicken, Autor, Text und Bild wählen.": "Here under “Posts”, click “+ Post” and choose author, text and picture.",
"Entscheiden, wann er erscheint: „automatisch“ mit 🔒 Bedingung (z. B. ab Tag 3) oder „nur per Aktion“ – dann die Aktion „📸 Beitrag posten“ an eine Auswahl, ein Hub-Objekt oder ein Minispiel hängen.": "Decide when it appears: “automatically” with a 🔒 condition (e.g. from day 3) or “only via action” – then attach the action “📸 Post” to a choice, a hub object or a minigame.",
"Mit „▶ Vorschau“ ansehen.": "Check it with “▶ Preview”.",
"Beitrag nach einer Entscheidung": "Post after a decision",
"Beitrag anlegen und auf „nur per Aktion“ stellen.": "Create a post and set it to “only via action”.",
"In der Szene die Antwort „Ray helfen“ anklicken.": "In the scene, click the answer “Help Ray”.",
"Bei „Aktionen“ „📸 Beitrag posten“ wählen und den Beitrag aussuchen.": "Under “Actions”, choose “📸 Post” and pick the post.",
"Follower wachsen lassen": "Grow followers",
"Unter „Profile“ den Startwert eintragen (z. B. 120).": "Enter the starting value under “Profiles” (e.g. 120).",
"An eine Antwort oder ein Ereignis die Aktion „👥 Follower ändern“ hängen, z. B. +200 oder +50 %.": "Attach the action “👥 Change followers” to an answer or event, e.g. +200 or +50 %.",
"Mit der Bedingung „👥 Follower mindestens …“ etwas freischalten.": "Unlock something with the condition “👥 Followers at least …”.",
"Links im Text": "Links in the text",
"Im Text „@Ray“ schreiben – im Spiel öffnet ein Klick Rays Profil (auch Namen mit Leerzeichen wie „@Wache Bernd“).": "Write “@Ray” in the text – in the game, a click opens Ray’s profile (names with spaces like “@Wache Bernd” work too).",
"„#Gildenfest“ schreiben – ein Klick zeigt alle Beiträge mit diesem Hashtag.": "Write “#Gildenfest” – a click shows all posts with this hashtag.",
"Das klappt in Beiträgen, Kommentaren und Profiltexten.": "This works in posts, comments and bios.",
"Ein Beitrag verschwindet nach einem Ereignis („🗑 Beitrag löschen“) – wer ihn vorher gesehen hat, weiß mehr.": "A post disappears after an event (“🗑 Delete post”) – whoever saw it before knows more.",
"Likes und Kommentare des Spielers geben Beziehungspunkte – oder kosten welche.": "The player’s likes and comments give relationship points – or cost some.",
"Mehrere Figuren posten nach einem großen Ereignis, jede aus ihrer Sicht.": "After a big event, several characters post, each from their point of view.",
"Ein #Hashtag als Spur: Unter #Vermisst sammeln sich Hinweise.": "A #hashtag as a trail: clues gather under #Missing.",
"Neu hier? Eigene Websites in 4 Schritten": "New here? Your own websites in 4 steps",
"1. „+ Website“ und eine Adresse wählen (z. B. gildenmarkt.ra). 2. Auf der Fläche Texte, Bilder, Knöpfe und Eingabefelder hinzufügen und mit der Maus verschieben. 3. Knöpfen einen Link auf eine andere Seite oder eine Aktion geben. 4. Dem Handy oder Computer die App „Browser“ geben. Mehr mit 💡.": "1. Click “+ Website” and choose an address (e.g. gildenmarkt.ra). 2. Add texts, images, buttons and input fields on the canvas and move them with the mouse. 3. Give buttons a link to another page or an action. 4. Give the phone or computer the “Browser” app. More with 💡.",
"Noch kein Gerät hat die App „Browser“.": "No device has the “Browser” app yet.",
"App „Browser“ auch auf:": "Also add the “Browser” app to:",
