"Tipp: Andere Elemente mit 🔒 „Passwort eingegeben“ erst danach zeigen.": "Tip: show other elements only afterwards with 🔒 “Password entered”.",
"Suchbegriffe → Treffer. Mehrere Begriffe mit Komma trennen.": "Search terms → results. Separate several terms with commas.",
"Begriffe": "Terms",
"Element nur zeigen, wenn …": "Only show element if …",
"Links funktionieren in der Vorschau, Aktionen laufen erst im Spiel.": "Links work in the preview; actions only run in the game.",
"Websites – so geht’s": "Websites – how it works",
"Eigene Webseiten für den Browser im Handy oder Computer des Spiels. Jede Website hat eine Adresse (z. B. www.gildenmarkt.ra) und beliebig viele Seiten. Auf jeder Seite platzierst du Texte, Bilder, Knöpfe, Flächen und Eingabefelder frei – wie im Menü-Designer.": "Your own web pages for the browser on the in-game phone or computer. Every website has an address (e.g. www.gildenmarkt.ra) and as many pages as you like. On each page you place texts, images, buttons, shapes and input fields freely – like in the menu designer.",
"Recherche, Geheimnisse und Weltenbau: Der Spieler sucht Hinweise im Netz, knackt ein Passwort, kauft in einem Online-Shop ein oder liest Nachrichten über die Spielwelt.": "Research, secrets and worldbuilding: the player looks for clues online, cracks a password, shops online or reads news about the game world.",
"„+ Website“ klicken, Namen und Adresse eintragen.": "Click “+ Website”, enter name and address.",
"Mit „+ Text“, „+ Bild“, „+ Knopf“ … Elemente hinzufügen und auf der Fläche verschieben, an der Ecke unten rechts die Größe ändern.": "Add elements with “+ Text”, “+ Image”, “+ Button” … and move them on the canvas; resize at the bottom-right corner.",
"Rechts beim gewählten Element Farben, Schrift, Link oder Aktion einstellen.": "Set colors, font, link or action for the selected element on the right.",
"Mit „+ Seite“ weitere Seiten anlegen und per Link verbinden.": "Create more pages with “+ Page” and connect them with links.",
"Unter Geräte dem Handy oder Computer die App „Browser“ geben – oder oben auf „Zu … hinzufügen“ klicken.": "Under Devices, give the phone or computer the “Browser” app – or click “Add to …” above.",
"Geheimes Postfach mit Passwort": "Secret mailbox with password",
"Website „mail.gilde.ra“ anlegen und auf „geheim“ stellen.": "Create the website “mail.gilde.ra” and set it to “secret”.",
"Ein Eingabefeld als Passwort-Feld, richtiges Passwort z. B. „katze123“.": "An input field as password field, correct password e.g. “katze123”.",
"Bei „Richtig → Seite“ die Seite mit den Mails wählen.": "Under “Correct → page”, choose the page with the mails.",
"Suchmaschine": "Search engine",
"Website „sucher.ra“ mit einem Suchfeld.": "Website “sucher.ra” with a search field.",
"Treffer anlegen: Begriffe „Ray, Diebin“ → Seite mit Rays Steckbrief.": "Create results: terms “Ray, thief” → page with Ray’s wanted poster.",
"Nur wer den Namen kennt, findet die Seite.": "Only those who know the name find the page.",
