"· Teil ziehen = drehen · gelbes Quadrat / Pfeile oder Alt + Ziehen = ganze Figur verschieben · Doppelklick = festpinnen · Rahmen in der Spur = mehrere Keys · Strg+C / Strg+V": "· drag a part = rotate · yellow square / arrows or Alt + drag = move the whole figure · double-click = pin · box in the track = several keys · Ctrl+C / Ctrl+V",
"· Knochen-Griff ziehen = Keyframe · Figur ziehen (Alt + Ziehen) = ganze Figur bewegen · Raute ziehen = verschieben · Rahmen in der Spur = mehrere Keys · Strg+C / Strg+V · Entf = löschen": "· drag a bone handle = keyframe · drag the figure (Alt + drag) = move the whole figure · drag a diamond = move · box in the track = several keys · Ctrl+C / Ctrl+V · Del = delete",
"Doppeln – mit der gleichen Animation (Keyframes, Idle, Wackeln). Gut, um z. B. einen Arm vor und einen hinter eine Figur zu legen.": "Duplicate – with the same animation (keyframes, idle, jiggle). Handy to put e.g. one arm in front of and one behind a figure.",
"Weiter nach vorne (über andere Darsteller)": "Bring forward (above other actors)",
