"Das Bild füllt die ganze Blase; Ecken, Randstärke und Rand wirken wie ohne Bild.": "The image fills the whole bubble; corners, border width and border work as without an image.",
"Rahmen-Bild als 9-Slice. „Ecken“ (oben bei Form) rundet die Blase trotzdem ab; für ein Hintergrundbild ohne Rahmen „Bild füllt die Blase“ wählen.": "Frame image as 9-slice. “Corners” (under Shape above) still rounds the bubble; for a background picture without a frame choose “Image fills the bubble”.",
