"Zeigt den Darsteller nur innerhalb (oder außerhalb) einer Form – z. B. ein Arm, der hinter einer anderen Figur verschwindet.": "Shows the actor only inside (or outside) a shape – e.g. an arm that disappears behind another figure.",
