"Form neu zeichnen": "Redraw shape",
"Bearbeiten: Fläche ziehen = verschieben · Ecke = Größe · Kreis = drehen · Punkte ziehen · Umschalt + Klick = Punkt hinzufügen · Alt + Klick auf Punkt = löschen": "Edit: drag the area = move · corner = size · circle = rotate · drag points · Shift + click = add point · Alt + click on a point = delete",
"Bearbeiten: Fläche ziehen = verschieben · Ecke unten rechts = Größe · Kreis oben = drehen. Mit Keyframes bewegt sich die Maske mit.": "Edit: drag the area = move · bottom-right corner = size · circle on top = rotate. With keyframes the mask moves along.",
"Follower als Spielmechanik": "Followers as a game mechanic",
"Follower können wachsen, Belohnung sein (Aktion „👥 Follower ändern“, z. B. als Quest- oder Minispiel-Belohnung) und Bedingung (z. B. ein Schwarm mag nur jemanden mit Reichweite).": "Followers can grow, be a reward (action “👥 Change followers”, e.g. as a quest or minigame reward) and a condition (e.g. a crush only likes someone with reach).",
"Als Währung": "As a currency",
"— keine (eigene Zahl) —": "— none (own number) —",
"Lege zuerst unter „Währungen“ eine Währung an (z. B. „Follower“).": "First create a currency under “Currencies” (e.g. “Followers”).",
"Mit Währung: Follower lassen sich ausgeben, im Idler erzeugen (Gebäude produziert Follower) und im HUD anzeigen. Idler und Social Media nutzen dieselbe Zahl.": "With a currency: followers can be spent, produced in the idler (a building produces followers) and shown in the HUD. Idler and social media share the same number.",
"Wachstum über die Zeit": "Growth over time",
"Wachstum läuft mit dem Kalender. Schalte unter „Lebenssimulation“ die Tageszeit ein – jeder neue Tag wendet die Regeln an.": "Growth runs with the calendar. Turn on time of day under “Life simulation” – every new day applies the rules.",
"jeden Tag": "every day",
"jede Woche": "every week",
"an einem Wochentag": "on a weekday",
"% (wächst mit)": "% (compounds)",
