"Setze linken und rechten Mundwinkel und das Kinn. Kommt ein Objekt auf die Mundmitte zu, senkt sich der Unterkiefer so weit, wie das Objekt dort breit ist. Was schon im Mund ist, sieht man nur noch durch die Öffnung.": "Set the left and right mouth corners and the chin. When an object comes toward the middle of the mouth, the lower jaw drops as far as the object is wide there. What is already in the mouth is only visible through the opening.",
