"Form oben": "Shape above",
"beliebige Form mit Transparenz": "any shape with transparency",
"In der Vorschau ziehen: orange Punkte = Textfläche, blaue Punkte = Namensfeld, Fläche ziehen = Fläche verschieben, daneben auf die Blase ziehen = ganze Blase verschieben. Wo die Fläche schmaler ist, wird der Text kleiner.": "Drag in the preview: orange points = text area, blue points = name field, drag an area = move it, drag on the bubble next to it = move the whole bubble. Where the area is narrower, the text gets smaller.",
