"Für Beta-Tester und Modder: Taste ^ öffnet im fertigen Spiel die Entwickler-Konsole (Werte setzen, springen …).",
"Gelten überall, wo an der Aktion selbst kein Bild gewählt ist. Ein Bild direkt an der Aktion hat immer Vorrang.",
