"Mit Bones bewegt sich ein einzelnes Bild sanft: Atmen, Schwanken, Arme schwingen, Haare und Flügel wippen nach.",
"Rot = etwas fehlt oder ist kaputt. Maus darüber zeigt den Grund, Klick auf die Zeile öffnet rechts alle Felder.",
"Bilder und Audio aus der Dateiliste auf eine Spur ziehen. Doppelklick auf eine Spur legt einen leeren Clip an.",
"Die Bühne im Editor ist genau so groß wie später das Spiel. Du kannst das später beim Exportieren noch ändern.",
"Eine lange Aufnahme mit vielen Sätzen? „Schneiden“ → „Teile erkennen“ → automatisch auf die Dialoge verteilen.",
"Wähle oben „Augen markieren“ und ziehe ein Rechteck um jedes Auge. Oder nimm ein Bild mit geschlossenen Augen.",
"Hintergründe automatisch an die Tageszeit anpassen (wenn beim Hintergrund keine eigene Tageszeit gewählt ist)",
