"Lücken an einem Teil maskieren und mit einem passenden Farbverlauf füllen – läuft ohne KI-Modell": "Mask gaps on a part and fill them with a matching color gradient – works without an AI model",
"Inpaint-Stift: Teil wählen und die Lücke maskieren – Lasso = umfahren, Lineal = Punkte anklicken (Doppelklick oder Enter schließt), Pinsel = übermalen · Alt = von der Maske abziehen · Enter oder „Füllen“ füllt die Maske · Strg + Z macht das Füllen rückgängig. Gespeichert wird als neue Bilddatei, das Original bleibt erhalten.": "Inpaint brush: select a part and mask the gap – Lasso = draw around it, Ruler = click points (double-click or Enter closes), Brush = paint over it · Alt = subtract from the mask · Enter or “Fill” fills the mask · Ctrl + Z undoes the fill. Saved as a new image file, the original is kept.",
"Ungespeicherte Änderungen am Bild verwerfen?": "Discard unsaved changes to the image?",
"Erst die Lücke maskieren": "Mask the gap first",
"Erst Punkt A und B auf dem Bild setzen": "Set points A and B on the image first",
"Am Rand der Maske gibt es keine Farben – Maske etwas über das Bild ziehen oder eine Farbe wählen": "There are no colors at the edge of the mask – extend the mask slightly over the image or choose a color",
"Erst ein Teil anklicken": "Click a part first",
"Dieser Platz hat noch kein Bild": "This slot has no image yet",
"Dort ist keine Farbe – auf eine sichtbare Stelle klicken": "There is no color there – click a visible spot",
"Dieses Teil hat Bones – mehr Platz würde sie verschieben": "This part has bones – more room would shift them",
"Teil auf der Fläche anklicken, dann die Lücke maskieren.": "Click a part on the stage, then mask the gap.",
