"Punkt B setzen": "Set point B",
"Jetzt auf die Stelle klicken, deren Farbe du möchtest.": "Now click the spot whose color you want.",
"Maske löschen": "Clear mask",
"Durchsichtigen Rand um das Bild legen, falls die Lücke außerhalb liegt. Das Teil bleibt an seiner Stelle.": "Add a transparent border around the image if the gap lies outside it. The part stays in place.",
"Mehr Platz am Rand": "More room at the edge",
"Vom Rand: Die Farben am Maskenrand laufen weich ineinander – am besten die Maske etwas über das vorhandene Bild ziehen. Weichheit blendet die Füllung über dem vorhandenen Bild ein. Gespeichert wird als neue Bilddatei – das Original bleibt erhalten.": "From the edge: the colors at the edge of the mask blend softly into each other – it works best if the mask slightly overlaps the existing image. Softness blends the fill over the existing image. Saved as a new image file – the original is kept."
